    ) -> ReelOp {
        var a = OpArgs()
        a.put("clip", clip)
        a.put("action", action)
        a.put("patch", patch)
        if !off.isEmpty { a.put("off", off) }
        a.put("schema", schema)
        return ReelOp(name: "set_action_end", args: a.values)
    }

    /// Merges into the action's end patch. A typed `.some(nil)` — a switch
