                    off.append("audio.eq.\(slot)")
                    eq[slot] = nil
                }
                fields["eq"] = eq
            }
            groups[group] = fields
        }
        return setActionEndRaw(clip: clip, action: action, patch: groups, off: off.sorted(), schema: schema)
    }

