    /// A clip's rate (spec §11 SR-21 (b)): `.defaults` answers ×1; at `.end`
    /// the selected action's stored `end.speed` when it names one; otherwise
    /// the core's rate in force at the read's time (`clip_state`'s `speed`),
    /// or the clip's base `speed` when no time is read. No rate is computed
    /// here (D2-1).
    func speed(_ clip: ClipSnapshot) -> Double {
        if mode == .defaults { return 1 }
        if mode == .end, let named = action(clip)?.end.speed { return named }
        return evaluated(clip).speed ?? clip.speed
    }
    /// Shapes are not animatable (§5.4's patch covers video, audio and text),
    /// so this is always the base description.
    func shape(_ clip: ClipSnapshot) -> ShapeProps {
        mode == .defaults ? ShapeProps() : clip.shape ?? ShapeProps()
    }

    /// The list a WRITE of a list-valued video key must be built from — and
    /// the length `structural` below must measure a new one against.
    ///
    /// `video(_:)` answers what the playhead SHOWS, which is what every `read:`
    /// closure in the inspector wants and what every row displays. It is the
    /// wrong list to build an EDIT out of. Inside an action a write lands on
    /// the action's END patch, and `actions.rs`'s `merge` replaces an array
    /// whole rather than entry by entry, so an array built from the
    /// interpolated values pins every entry the user did not touch at whatever
    /// it happened to read at the playhead: with a base of
    /// `[blur 0.2, sepia 0.3]` and an end of `[blur 1.0, sepia 0.3]`, dialling
    /// the sepia at the midpoint re-sends the blur at 0.6 and its ramp is
    /// silently flattened.
    ///
    /// So a write reads the list it is about to REPLACE — the action's own end
    /// `filters` or `obscure` when the end patch carries one, and the clip's
    /// base list when it does not. The same answer is what a new length has to
    /// be compared against, for the same reason read the other way: that array
    /// is the one an end patch must match to interpolate at all, and comparing
    /// against the base alone made the section rewrite the clip's base stack
    /// whenever an earlier action had already changed the count.
    ///
    /// Note what this is NOT: it is not the list at the action's START, which
    /// is the truly exact answer and needs a second `clip_state` call at a
    /// time nothing else in the inspector asks about. The pair above agrees
    /// with it in every case the inspector can produce, because the section
    /// can only ever write the length it can see.
    /// the middle two. Only `.applied` opens the explicit group: an empty one
    /// is still a step on the stack, and closing it clears redo (#59).
    private func commitEdit(_ actionName: String, _ ops: [ReelOp], grouped: Bool) {
        let current = project
        do {
            switch try current.applying(addressed(ops)) {
            case .applied(let updated):
                func commit() {
                    registerUndo(restoring: current, actionName: actionName)
                    project = updated
                    countEditChange(.changeDone)
                    projectDidChange()
                }
                if grouped { inExplicitUndoGroup(commit) } else { commit() }
            case .identity:
                NSSound.beep()
            case .refused(let refusal):
                // The identity's beep and NO undo step, then the sentence.
                NSSound.beep()
                NotificationCenter.default.post(
                    name: .projectDocumentDidRefuse, object: self,
                    userInfo: ["refusal": refusal])
            }
        } catch {
            present(error)
        }
    }

    /// **Pitfall** (app/CLAUDE.md): a registration made outside an event lands
    /// in the implicit per-event group AppKit never closes here, so every such
    /// edit silently merges into ONE undo step. The fix is event grouping OFF
    /// for the duration and a balanced explicit group, **not** forcing the
    /// level to zero: that leaves an end with no begin, the checkpoint
    /// `NSDocument` posts inside every save's file-coordination accessor then
    /// raises `endUndoGrouping called with no matching begin`, the coordinator
    /// swallows it under `autosavesInPlace`, and ⌘S and `save_project` hang
    /// for good, every later file access blocking behind the unreleased claim.
    private func inExplicitUndoGroup(_ body: () -> Void) {
        guard let manager = undoManager else { return body() }
        let groupsByEvent = manager.groupsByEvent
        if groupsByEvent { manager.groupsByEvent = false }
        let level = manager.groupingLevel
        manager.beginUndoGrouping()
        body()
        // Close exactly what this call opened — never a group it did not.
        while manager.groupingLevel > level { manager.endUndoGrouping() }
        if groupsByEvent { manager.groupsByEvent = true }
    }

